r"""Hand-written derivations for Verina tasks, batch S (advanced: frequency ranking)."""
from benchmarks.datasets.derivation_dsl import bind, cases, loop, term, with_lemmas

_E76 = '(nums.eraseDups.mergeSort (fun x y => decide (nums.count y ≤ nums.count x))).take k'
_NDAUX = {"name": "nodup_eraseDups_aux", "statement": "∀ (n : Nat) (l : List Int), l.length ≤ n → l.eraseDups.Nodup",
          "proof": 'by\n  intro n\n  induction n with\n  | zero => intro l hl; have : l = [] := List.eq_nil_of_length_eq_zero (by omega); subst this; simp\n  | succ n ih =>\n    intro l hl\n    cases l with\n    | nil => simp\n    | cons a t =>\n      rw [List.eraseDups_cons, List.nodup_cons]\n      constructor\n      · intro hmem\n        rw [List.mem_eraseDups, List.mem_filter] at hmem\n        simp at hmem\n      · apply ih\n        have := List.length_filter_le (fun b => !b == a) t\n        simp at hl ⊢; omega\n'}
_ND = {"name": "nodup_eraseDups", "statement": "∀ (l : List Int), l.eraseDups.Nodup",
       "proof": "by intro l\n  exact nodup_eraseDups_aux l.length l (le_refl _)"}
_L76 = {"name": "topk76", "statement": "∀ (nums : List Int) (k : Nat) (h : topKFrequent_precond nums k), topKFrequent_postcond nums k (" + _E76 + ") h",
        "proof": 'by\n  intro nums k h\n  have hk : k ≤ nums.eraseDups.length := h\n  have hperm := List.mergeSort_perm nums.eraseDups (fun x y => decide (nums.count y ≤ nums.count x))\n  have hsorted : List.Pairwise (fun x y => decide (nums.count y ≤ nums.count x) = true)\n      (nums.eraseDups.mergeSort (fun x y => decide (nums.count y ≤ nums.count x))) :=\n    List.pairwise_mergeSort (by intro a b c h1 h2; simp at *; omega) (by intro a b; simp; omega) _\n  have hnd : (nums.eraseDups.mergeSort (fun x y => decide (nums.count y ≤ nums.count x))).Nodup :=\n    hperm.nodup_iff.mpr (nodup_eraseDups nums)\n  have hlen : (nums.eraseDups.mergeSort (fun x y => decide (nums.count y ≤ nums.count x))).length = nums.eraseDups.length :=\n    hperm.length_eq\n  generalize hM : nums.eraseDups.mergeSort (fun x y => decide (nums.count y ≤ nums.count x)) = M at hsorted hnd hlen\n  have hmem : ∀ x, x ∈ M ↔ x ∈ nums := by\n    intro x; rw [← hM, hperm.mem_iff, List.mem_eraseDups]\n  unfold topKFrequent_postcond\n  refine ⟨by simp; omega, ?_, ?_, ?_, ?_⟩\n  · rw [List.all_eq_true]; intro x hx\n    simpa using (hmem x).mp (List.mem_of_mem_take hx)\n  · exact (hnd.sublist (List.take_sublist _ _))\n  · rw [List.all_eq_true]; intro x hx\n    rw [List.all_eq_true]; intro y hy\n    simp only [decide_eq_true_eq]\n    by_cases hyr : y ∈ M.take k\n    · exact Or.inl hyr\n    · right\n      have hyM : y ∈ M := (hmem y).mpr (by simpa using hy)\n      have hyd : y ∈ M.drop k := by\n        have := hyM\n        rw [← List.take_append_drop k M] at this\n        rcases List.mem_append.mp this with h | h\n        · exact absurd h hyr\n        · exact h\n      have hpw := hsorted\n      rw [← List.take_append_drop k M, List.pairwise_append] at hpw\n      have := hpw.2.2 x hx y hyd\n      simpa using this\n  · have hpw : List.Pairwise (fun x y => decide (nums.count y ≤ nums.count x) = true) (M.take k) :=\n      hsorted.sublist (List.take_sublist _ _)\n    rw [List.pairwise_iff_getElem] at hpw ⊢\n    intro a b ha hb hab\n    simp only [List.length_zipIdx] at ha hb\n    simp only [List.getElem_zipIdx]\n    intro _\n    have := hpw a b ha hb hab\n    simpa using this\n'}

